export const scannerMarkup=`<div class="scanner-view"><video id="scan-video" playsinline muted hidden></video><div id="scanner-placeholder"><svg width="62" height="62" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3"><path d="M3 9V3h6m6 0h6v6m0 6v6h-6m-6 0H3v-6M7 7h3v3H7zM14 7h3v3h-3zM7 14h3v3H7zM14 14h3v3h-3z"/></svg><p>Escanea el QR de tu ticket</p></div></div><p id="scanner-message" class="compact-note" aria-live="polite"></p><div class="data-actions section-gap"><button class="button wide" id="scanner-camera" type="button">Usar cámara</button><label class="button outline wide" for="scanner-photo">Elegir foto del QR</label><input type="file" id="scanner-photo" accept="image/*" class="sr-only"></div>`;
export function mountScanner(dialog,onCode){
 const video=dialog.querySelector('#scan-video'),photo=dialog.querySelector('#scanner-photo'),cameraButton=dialog.querySelector('#scanner-camera'),message=dialog.querySelector('#scanner-message'),placeholder=dialog.querySelector('#scanner-placeholder');
 const canvas=document.createElement('canvas'),context=canvas.getContext('2d',{willReadFrequently:true});let stream=null,timer=null,closed=false,busy=false;
 function stopCamera(){clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;}
 function cleanup(){if(closed)return;closed=true;stopCamera();dialog.removeEventListener('close',cleanup);dialog.removeEventListener('cancel',cleanup);document.removeEventListener('visibilitychange',onVisibility);cameraButton.removeEventListener('click',start);photo.removeEventListener('change',readPhoto);}
 function onVisibility(){if(document.hidden){stopCamera();video.hidden=true;placeholder.hidden=false;cameraButton.disabled=false;cameraButton.textContent='Usar cámara';}}
 function deliver(value){try{if(onCode(value)!==false){cleanup();return true;}}catch(error){message.textContent=error.message;}return false;}
 function decode(source,width,height,maxWidth=900){const scale=Math.min(1,maxWidth/Math.max(width,height));canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));context.drawImage(source,0,0,canvas.width,canvas.height);const data=context.getImageData(0,0,canvas.width,canvas.height);return globalThis.jsQR(data.data,data.width,data.height,{inversionAttempts:'dontInvert'});}
 function tick(){if(closed||!stream)return;if(video.readyState>=2&&video.videoWidth){const code=decode(video,video.videoWidth,video.videoHeight,640);if(code&&deliver(code.data))return;}timer=setTimeout(tick,180);}
 async function start(){if(closed||busy||stream)return;busy=true;cameraButton.disabled=true;message.textContent='Abriendo cámara…';try{if(!navigator.mediaDevices?.getUserMedia||!window.isSecureContext)throw Error('Para usar la cámara, abre el enlace HTTPS de AutoBox en Chrome. Aquí puedes elegir una foto del QR.');const requested=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280}},audio:false});if(closed){requested.getTracks().forEach(t=>t.stop());return;}stream=requested;video.srcObject=stream;video.hidden=false;placeholder.hidden=true;await video.play();message.textContent='Apunta al QR del boleto.';tick();}catch(error){stopCamera();video.hidden=true;placeholder.hidden=false;message.textContent=error.name==='NotAllowedError'?(!['http:','https:'].includes(location.protocol)?'El visor de archivos bloqueó la cámara. Abre el enlace HTTPS de AutoBox en Chrome.':'Chrome bloqueó el permiso. Revisa Configuración del sitio → Cámara → Permitir. También puedes elegir una foto del QR.'):error.message;cameraButton.disabled=false;}finally{busy=false;}}
 async function readPhoto(){const file=photo.files?.[0];if(!file||closed)return;stopCamera();video.hidden=true;placeholder.hidden=false;cameraButton.disabled=false;message.textContent='Leyendo QR…';let objectURL;try{if(file.size>20*1024*1024)throw Error('Elige una imagen de menos de 20 MB.');objectURL=URL.createObjectURL(file);const image=new Image();image.src=objectURL;await image.decode();if(closed)return;const code=decode(image,image.naturalWidth,image.naturalHeight,1400);if(!code)throw Error('No se encontró un QR. Prueba con una foto más nítida.');deliver(code.data);}catch(error){if(!closed)message.textContent=error.message;}finally{if(objectURL)URL.revokeObjectURL(objectURL);photo.value='';}}
 cameraButton.addEventListener('click',start);photo.addEventListener('change',readPhoto);dialog.addEventListener('close',cleanup);dialog.addEventListener('cancel',cleanup);document.addEventListener('visibilitychange',onVisibility);return cleanup;
}
